"use strict";(self.webpackChunkbed_mega_textbook=self.webpackChunkbed_mega_textbook||[]).push([[8208],{1459(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>c,default:()=>l,frontMatter:()=>a,metadata:()=>i,toc:()=>u});const i=JSON.parse('{"id":"eed-313/unit-03/unit-teacher-notes","title":"Unit 3 teacher notes","description":"EED-313 Unit 3 tutor guidance: sequencing the four topics, the misconceptions to probe, managing the activities, and practicum links for routines, subject routines and collaborative learning.","source":"@site/licence/eed-313/unit-03/unit-teacher-notes.mdx","sourceDirName":"eed-313/unit-03","slug":"/eed-313/unit-03/unit-teacher-notes","permalink":"/licence/eed-313/unit-03/unit-teacher-notes","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Unit 3 teacher notes","description":"EED-313 Unit 3 tutor guidance: sequencing the four topics, the misconceptions to probe, managing the activities, and practicum links for routines, subject routines and collaborative learning.","course_code":"EED-313","unit_no":3,"clo_refs":["SLO:EED-313-3-5"],"blooms_summary":"Guidance for tutors sequencing Unit 3: how to move trainees from seeing routines as rigid rules to seeing them as time-recovery tools; how to run the four topic activities; what misconceptions to probe; and how to design the practicum tasks so they produce usable evidence.","est_reading_minutes":6,"translation_status":"draft"},"sidebar":"licenceSidebar","previous":{"title":"Unit 3 assessment","permalink":"/licence/eed-313/unit-03/unit-assessment"},"next":{"title":"Creating shared values and community","permalink":"/licence/eed-313/unit-04/"}}');var s=n(4848),o=n(8453),r=n(6606);const a={title:"Unit 3 teacher notes",description:"EED-313 Unit 3 tutor guidance: sequencing the four topics, the misconceptions to probe, managing the activities, and practicum links for routines, subject routines and collaborative learning.",course_code:"EED-313",unit_no:3,clo_refs:["SLO:EED-313-3-5"],blooms_summary:"Guidance for tutors sequencing Unit 3: how to move trainees from seeing routines as rigid rules to seeing them as time-recovery tools; how to run the four topic activities; what misconceptions to probe; and how to design the practicum tasks so they produce usable evidence.",est_reading_minutes:6,translation_status:"draft"},c="Unit 3 teacher notes",h={},u=[{value:"Sequencing note",id:"sequencing-note",level:2},{value:"Common misconceptions to probe",id:"common-misconceptions-to-probe",level:2},{value:"Managing the activities",id:"managing-the-activities",level:2},{value:"Practical work and practicum links",id:"practical-work-and-practicum-links",level:2},{value:"A note on the figures",id:"a-note-on-the-figures",level:2},{value:"Assessment note",id:"assessment-note",level:2}];function d(e){const t={h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(r.A,{}),"\n",(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"unit-3-teacher-notes",children:"Unit 3 teacher notes"})}),"\n",(0,s.jsx)(t.h2,{id:"sequencing-note",children:"Sequencing note"}),"\n",(0,s.jsx)(t.p,{children:"The four topics follow the logic of a single week. Topic 3.1 asks what routines are and why they\nbuy time; Topic 3.2 asks how to adapt them when the room makes one-size-fits-all impossible;\nTopic 3.3 asks what subject-specific routines look like; Topic 3.4 asks how to design routines that\nbuild co-operation and collaborative learning."}),"\n",(0,s.jsx)(t.p,{children:"A useful session order is to teach the topics in numerical order across the three weeks the guide\nallows (Weeks 9 to 11), using the first session of the unit to time a real transition and the last\nto rehearse the integrative assessment. The unit is designed so that a tutor who needs to compress\nit can merge the activity time of Topics 3.1 and 3.2 into a single routine-design workshop without\nlosing the conceptual spine."}),"\n",(0,s.jsx)(t.h2,{id:"common-misconceptions-to-probe",children:"Common misconceptions to probe"}),"\n",(0,s.jsx)(t.p,{children:"These are the misconceptions the unit names explicitly. Surface them early and return to them;\ntrainees often assent to the correct version in a discussion and then revert when they plan."}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"Routines make a classroom rigid."'}),' This is the most persistent one. Probe it by asking:\n"If the routine removes the need to negotiate every transition, what does the teacher gain?"\nTrainees who equate flexibility with absence of structure will find this counter-intuitive. The\nfigure in Topic 3.1 (routine, structure, procedure, rule distinguished) is designed to make the\ndistinction visible; use it as a poster or handout.']}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"Routines are for young children only."'}),' Probe it by asking: "What routine do you use every\nmorning before you come to university?" The content of the routine changes with age; the\nprinciple does not.']}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"Group work and collaborative learning are the same thing."'}),' This one belongs to Topic 3.4.\nProbe it by asking: "If four pupils sit together and one does all the work, is that\ncollaboration?" The answer is no, and the reason is the absence of individual accountability.']}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.h2,{id:"managing-the-activities",children:"Managing the activities"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 3.1 - Time one transition (practicum-based)."})," The key teaching move is the arithmetic:\nask trainees to bring their timed data and calculate the minutes recovered across a week. The\nnumber is the argument. If trainees cannot produce data, use the worked example in the figure\n(a week's recovered minutes, transition by transition) and ask them to verify the calculation."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 3.2 - Design an anchor routine (25 minutes)."}),' The trap is that trainees produce a task\ndescription rather than a routine. The difference: a task description says what pupils do; a\nroutine says how they start, what they do when stuck, how they check, and what they do when\nfinished. The debrief question - "identify one moment where a pupil might drift from working to\njust busy" - is designed to catch this.']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 3.3 - One routine, three subjects (25 minutes)."}),' Pairs work well here because the task is\na structured redesign, not a design from scratch. The key teaching move is the debrief: "What\nchanged because of the subject, not because of the pupils?" If trainees answer "the difficulty",\npush them back: the routine protects against a management risk, not a cognitive one.']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 3.4 - Design a collaborative routine (25 minutes)."}),' This is the most cognitively\ndemanding activity. The trap is that trainees produce roles without accountability. The debrief\nquestion - "identify one moment where a group might slip from collaborative to one person doing\nthe work" - is designed to catch this. If trainees cannot answer it, they have assigned roles but\nnot made them necessary.']}),"\n",(0,s.jsx)(t.h2,{id:"practical-work-and-practicum-links",children:"Practical work and practicum links"}),"\n",(0,s.jsx)(t.p,{children:'Each topic carries a "Try this at your practicum school" task. The unit works best when the tutor\nsets these up explicitly before trainees leave for practicum and debriefs them when trainees\nreturn.'}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 3.1 practicum task"})," (timing a transition) produces a simple data set. Use it to open\nTopic 3.2: ask trainees which transition lost the most time, and use their examples to motivate\nthe anchor routine."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 3.2 practicum task"})," (observe a multigrade room) produces the evidence trainees need\nfor ERQ 3. If the practicum school has no multigrade room, ask trainees to observe a single-grade\nroom and note the routines that would stop working if a second grade were added."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 3.3 practicum task"})," (observe one teacher across two subjects) produces a comparison.\nUse it to make the point that subject-specific routines are not arbitrary: they protect against\nthe friction each subject creates."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 3.4 practicum task"})," (tally the time across the three phases) produces a simple data\nset. Use it to make the point that most group work spends too long on set-up and too little on\nclosure, and that the close routine is where the learning transfers to the whole class."]}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.h2,{id:"a-note-on-the-figures",children:"A note on the figures"}),"\n",(0,s.jsx)(t.p,{children:"The unit carries eight figures: two concept-map figures that make a conceptual structure visible\n(fig-U3-1, fig-U3-7), two flowchart figures that sequence a process (fig-U3-4, and the\ncollaboration cycle), and four tables that compare options against a criterion (fig-U3-3, fig-U3-5,\nfig-U3-6, fig-U3-8). The tables are the ones trainees most often try to read as prose. Before you\nproject any of them, ask trainees to read the column headers first and say what the table is\ncomparing."}),"\n",(0,s.jsx)(t.h2,{id:"assessment-note",children:"Assessment note"}),"\n",(0,s.jsx)(t.p,{children:"The 10/10/5 bank is designed to be used in two passes: the MCQs and RRQs as formative checks at\nthe end of Topics 3.2 and 3.4, and the ERQs as a summative task at the end of the unit. ERQ 5 (the\nintegrative item) is the one that most reliably separates trainees who have understood the unit\nfrom those who have memorised its definitions. If you use only one ERQ, use that one."})]})}function l(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},6606(e,t,n){n.d(t,{A:()=>s});n(6540);var i=n(4848);function s(e){var t=e.label,n=void 0===t?"Print / Save as PDF":t;return(0,i.jsxs)("button",{type:"button",className:"print-handout print-hidden","aria-label":"Print or save this handout as a PDF",onClick:function(){return"undefined"!=typeof window&&window.print()},children:[(0,i.jsx)("span",{"aria-hidden":"true",children:"\ud83d\udda8 "}),n]})}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>a});var i=n(6540);const s={},o=i.createContext(s);function r(e){const t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);